private static int findNextSmallest(int n, int[] digits, int i, int j) {
    int[] result = new int[digits.length];
    int k = 0;
    for (int m = 0; m < digits.length; m++) {
        if (m != i && m != j) {
            result[k++] = digits[m];
        }
    }
    int smallest = format(result, reverse = true);
    return smallest;
}

private static int format(int[] digits, bool reverse) {
    int result = 0;
    int factor = 1;
    if (reverse) {
        for (int i = digits.length - 1; i >= 0; i--) {
            result += factor * digits[i];
            factor *= 10;
        }
    } else {
        for (int i = 0; i < digits.length; i++) {
            result += factor * digits[i];
            factor *= 10;
        }
    }
    return result;
}
